p=argparse.ArgumentParser(description=__doc__);p.add_argument('--system-apps',type=Path,required=True);p.add_argument('--runtime',type=Path,required=True);p.add_argument('--utilities-commit',required=True);p.add_argument('--xtensa-cc',type=Path,required=True);p.add_argument('--snapshot',action='store_true');p.add_argument('--utc',action='store_true');a=p.parse_args();system=a.system_apps.resolve();runtime=a.runtime.resolve()
pin=json.loads((ROOT/'sdk/stopwatch-native-sources.json').read_text());exact(ROOT,a.utilities_commit);exact(system,pin['system_apps']);exact(runtime,pin['runtime']);app=profile(a.utc)
