manifest={k:v for k,v in app.items() if k!='grants'};manifest['requires']=[dict(capability=c,api=v) for c,v in dict.fromkeys((g['capability'],g['api']) for g in app['grants'])];(out/'stopwatch.json').write_text(json.dumps(manifest,indent=2)+'\n');(out/'stopwatch.boot-policy.json').write_text(json.dumps({'manifest':'stopwatch.json','grants':app['grants']},indent=2)+'\n')
